import { fireEvent, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { TtsFinishedEventInfo } from "./TtsFinishedEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({
    title,
    onClose,
    children,
  }: {
    title: string;
    onClose: () => void;
    children: React.ReactNode;
  }) => (
    <div>
      <h1>{title}</h1>
      <button data-testid="event-details-close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  ),
}));

const baseEvent: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.TtsFinished,
  name: "tts_finished",
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    parseData: {},
  },
};

describe("TtsFinishedEventInfo", () => {
  it("renders the title", () => {
    renderWithProviders(<TtsFinishedEventInfo event={baseEvent} onClose={vi.fn()} />);

    expect(screen.getByText("TTS finished")).toBeInTheDocument();
  });

  it("calls onClose when close button is clicked", () => {
    const onClose = vi.fn();
    renderWithProviders(<TtsFinishedEventInfo event={baseEvent} onClose={onClose} />);

    fireEvent.click(screen.getByTestId("event-details-close"));
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("renders the event details accordion section", () => {
    renderWithProviders(<TtsFinishedEventInfo event={baseEvent} onClose={vi.fn()} />);

    expect(screen.getByText("Event details")).toBeInTheDocument();
  });

  describe("latency section", () => {
    it("shows latency accordion when voice_latency is present", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          voice_latency: {
            tts_time_to_first_byte_ms: 150,
            tts_total_time_ms: 400,
          },
        },
      };

      renderWithProviders(<TtsFinishedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByText("Latency per turn")).toBeInTheDocument();
    });

    it("shows latency pill from tts_time_to_first_byte_ms", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          voice_latency: {
            tts_time_to_first_byte_ms: 150,
            tts_total_time_ms: 400,
          },
        },
      };

      renderWithProviders(<TtsFinishedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByText("~150 ms")).toBeInTheDocument();
    });

    it("does not show latency section when voice_latency is absent", () => {
      renderWithProviders(<TtsFinishedEventInfo event={baseEvent} onClose={vi.fn()} />);

      expect(screen.queryByText("Latency per turn")).not.toBeInTheDocument();
    });

    it("does not show latency section when voice_latency is invalid", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          voice_latency: {} as never,
        },
      };

      renderWithProviders(<TtsFinishedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.queryByText("Latency per turn")).not.toBeInTheDocument();
    });
  });
});
